// Fibonacci naïve — O(2^n), impraticável pra n > 40
function fib(n: number): number {
  if (n < 2) return n;  // base
  return fib(n - 1) + fib(n - 2);  // recursão
}

function fibMemo(n: number, cache = new Map<number, number>()): number {
  if (n < 2) return n;
  if (cache.has(n)) return cache.get(n)!;
  const result = fibMemo(n - 1, cache) + fibMemo(n - 2, cache);
  cache.set(n, result);
  return result;
}
// O(n) tempo e espaço — cada subproblem resolve 1x só

function fibTab(n: number): number {
  if (n < 2) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}
// O(n) tempo, O(1) espaço — melhor que memoization

// Quantas edições pra transformar s1 em s2? (insert, delete, substitute)
function editDistance(s1: string, s2: string): number {
  const m = s1.length, n = s2.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (s1[i - 1] === s2[j - 1]) dp[i][j] = dp[i - 1][j - 1];
      else dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[m][n];
}
// Uso: fuzzy match "você quis dizer X?" (threshold ≤ 2 para typos)

// ❌ Pode estourar stack em lista grande
function traverse(node: Node | null): void {
  if (!node) return;
  visit(node);
  traverse(node.next);
}

// ✅ Iterativo — sem stack overflow
function traverse(node: Node | null): void {
  while (node) {
    visit(node);
    node = node.next;
  }
}

// Tree: use stack explícita
function dfs(root: TreeNode): void {
  const stack = [root];
  while (stack.length) {
    const node = stack.pop()!;
    visit(node);
    for (const child of node.children) stack.push(child);
  }
}
